INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '105', 1, 'align-HG-2026-11-24', '{"tag":"8JD5","type":"theorem","title":"GRH for Dirichlet $L$-functions","statement_tex":"Let $\\chi$ be a \\hyperref[8JA9]{Dirichlet character} modulo $N$, let $\\chi_0$ be the \\hyperref[8JE3]{principal character} modulo $N$, and let $L(s,\\chi)$ be the \\hyperref[8JC4]{Dirichlet $L$-function}. Then\n\\[ L(s,\\chi) \\ne 0 \\qquad \\text{whenever } \\Re s > \\tfrac12 \\text{ and } (\\chi, s) \\ne (\\chi_0, 1), \\tag{H} \\]\n\\[ L(\\rho,\\chi) = 0 \\text{ and } 0 < \\Re\\rho < 1 \\implies \\Re\\rho = \\tfrac12. \\tag{G} \\]\nFor $N = 1$ this is the Riemann hypothesis.","section_id":101,"position":6,"listed":1,"aliases":["grh"]}', '(before history)');
UPDATE results SET statement_tex = 'Let $\chi$ be a \hyperref[8JA9]{Dirichlet character} modulo $N$, let $\chi_0$ be the \hyperref[8JE3]{principal character} modulo $N$, and let $L(s,\chi)$ be the \hyperref[8JC4]{Dirichlet $L$-function}. Then
\begin{alignat*}{2}
&\Re s > \tfrac12, \quad (\chi, s) \ne (\chi_0, 1) &\qquad& \implies \quad L(s,\chi) \ne 0; \tag{H} \\
&0 < \Re\rho < 1, \quad L(\rho,\chi) = 0 && \implies \quad \Re\rho = \tfrac12. \tag{G}
\end{alignat*}
For $N = 1$ this is the Riemann hypothesis.', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 12:30:00', updated_by = 'claude' WHERE id = 105;
